-- KMR · Raw Material Planning: bill of material, materials, rates and the Nov'26 plan from the Excel sheets.
-- Adds / updates only; nothing is deleted. Safe to run twice. Needs 0107.
create or replace function pg_temp.rmp_load(pid uuid, d jsonb, with_month boolean, mon text) returns text language plpgsql as $f$
declare x jsonb; n_b int := 0; n_m int := 0; n_p int := 0;
begin
  for x in select * from jsonb_array_elements(d -> 'parts') loop
    insert into console.ops_records (customer_id, kind, code, name, data, active, updated_by)
    values (pid, 'parts', x ->> 'code', coalesce(x ->> 'name', ''), jsonb_build_object('source', 'RM planning sheet'), true, 'rm-sheet-import')
    on conflict (customer_id, kind, code) do nothing;
    n_p := n_p + 1;
  end loop;
  for x in select * from jsonb_array_elements(d -> 'materials') loop
    insert into console.ops_records (customer_id, kind, code, name, data, active, updated_by)
    values (pid, 'raw_materials', x ->> 'code', coalesce(x ->> 'name', ''), jsonb_strip_nulls(jsonb_build_object('supplier', nullif(x ->> 'supplier', ''), 'source', 'RM planning sheet')), true, 'rm-sheet-import')
    on conflict (customer_id, kind, code) do nothing;
    insert into console.rmp_stock (customer_id, material_code, on_hand_kg, rate, gst_pct, unit, supplier_text, spec_text, updated_by)
    values (pid, x ->> 'code', case when with_month then coalesce((x ->> 'on_hand')::numeric, 0) else 0 end, nullif(x ->> 'rate', '')::numeric, coalesce((x ->> 'gst')::numeric, 18), x ->> 'unit', nullif(x ->> 'supplier', ''), nullif(x ->> 'name', ''), 'rm-sheet-import')
    on conflict (customer_id, material_code) do update set rate = excluded.rate, gst_pct = excluded.gst_pct, unit = excluded.unit, supplier_text = excluded.supplier_text, spec_text = excluded.spec_text,
      on_hand_kg = case when with_month then excluded.on_hand_kg else console.rmp_stock.on_hand_kg end, updated_at = now();
    n_m := n_m + 1;
  end loop;
  for x in select * from jsonb_array_elements(d -> 'bom') loop
    insert into console.rmp_bom (customer_id, part_code, material_code, rm_kg, loss_pct, notes, updated_by)
    values (pid, x ->> 'part', x ->> 'material', (x ->> 'kg')::numeric, 0, 'from RM planning sheet (C/F)', 'rm-sheet-import')
    on conflict (customer_id, part_code, material_code) do update set rm_kg = excluded.rm_kg, updated_at = now();
    n_b := n_b + 1;
  end loop;
  if with_month then
    for x in select * from jsonb_array_elements(d -> 'partstock') loop
      insert into console.rmp_partstock (customer_id, month, part_code, safety_qty, rrs_qty, wip_qty, wip2_qty, sched_manual, updated_by)
      values (pid, mon, x ->> 'part', coalesce((x ->> 'safety')::numeric, 0), coalesce((x ->> 'rrs')::numeric, 0), coalesce((x ->> 'wip')::numeric, 0), coalesce((x ->> 'wip2')::numeric, 0), nullif(x ->> 'manual', '')::numeric, 'rm-sheet-import')
      on conflict (customer_id, month, part_code) do update set safety_qty = excluded.safety_qty, rrs_qty = excluded.rrs_qty, wip_qty = excluded.wip_qty, wip2_qty = excluded.wip2_qty, sched_manual = excluded.sched_manual, updated_at = now();
    end loop;
    for x in select * from jsonb_array_elements(d -> 'weeks') loop
      insert into console.rmp_plan_week (customer_id, month, material_code, week, planned_qty, received_qty, updated_by)
      values (pid, mon, x ->> 'material', (x ->> 'week')::smallint, (x ->> 'planned')::numeric, (x ->> 'received')::numeric, 'rm-sheet-import')
      on conflict (customer_id, month, material_code, week) do update set planned_qty = excluded.planned_qty, received_qty = excluded.received_qty, updated_at = now();
    end loop;
  end if;
  return n_p || ' parts, ' || n_m || ' materials, ' || n_b || ' BOM lines';
end $f$;

