  unit text; pat text; d jsonb; wm boolean;
begin
  foreach unit in array array['2', '1', '3'] loop
    select count(*), min(id::text)::uuid, string_agg(name || ' [' || coalesce(plant_code, '') || ']', ', ') into n, pid, cand
      from console.customers where parent_id is not null
       and (name ~* ('unit[ _-]*' || unit || '($|[^0-9])') or coalesce(plant_code, '') ~* ('(^|[^0-9a-z])(u|unit)?[ _-]*' || unit || '($|[^0-9])'));
    if n <> 1 then
      if unit = '2' then raise exception 'Could not tell which plant is Unit-2 (% found: %). Tell Claude the plant name.', n, coalesce(cand, 'none'); end if;
      raise notice 'Unit-% skipped: % plants matched (%).', unit, n, coalesce(cand, 'none'); continue;
    end if;
    d := case when unit = '2' then u2 else u13 end; wm := (unit = '2');
    raise notice 'Unit-%: %', unit, pg_temp.rmp_load(pid, d, wm, '2026-11');
  end loop;
end $$;
